css:
.bob{animation:bob 1.8s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center bottom}
.bob2{animation:bob 1.6s ease-in-out infinite alternate;animation-delay:-.5s;transform-box:fill-box;transform-origin:center bottom}
.bob3{animation:bob 1.4s ease-in-out infinite alternate;animation-delay:-1s;transform-box:fill-box;transform-origin:center bottom}
@keyframes bob{from{transform:translateY(0)}to{transform:translateY(-6px)}}
.walk{animation:walk 6s ease-in-out infinite alternate}
@keyframes walk{from{transform:translateX(0)}to{transform:translateX(60px)}}
.sneak{animation:sneak 3.5s ease-in-out infinite alternate}
@keyframes sneak{from{transform:translateX(-30px)}to{transform:translateX(10px)}}
.sun{animation:spin 30s linear infinite;transform-box:fill-box;transform-origin:center}
@keyframes spin{to{transform:rotate(360deg)}}
.cloud{animation:cloud 14s ease-in-out infinite alternate}
@keyframes cloud{from{transform:translateX(0)}to{transform:translateX(40px)}}
.peek{animation:peek 2.4s ease-in-out infinite;transform-box:fill-box;transform-origin:center bottom}
@keyframes peek{0%,100%{transform:translateY(14px)}40%,70%{transform:translateY(0)}}
.knock{animation:knock .9s ease-in-out infinite;transform-box:fill-box;transform-origin:left center}
@keyframes knock{0%,100%{transform:rotate(0)}50%{transform:rotate(-12deg)}}
.stomp{animation:stomp .7s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center bottom}
@keyframes stomp{from{transform:translateY(0)}to{transform:translateY(-8px)}}
.steam{animation:steam 2.5s ease-in-out infinite}
@keyframes steam{0%{opacity:0;transform:translateY(6px)}50%{opacity:.8}100%{opacity:0;transform:translateY(-14px)}}
.spark{animation:spark .8s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center}
@keyframes spark{from{opacity:.2;transform:scale(.6)}to{opacity:1;transform:scale(1.2)}}
.hammer{animation:hammer .8s ease-in-out infinite;transform-box:fill-box;transform-origin:right bottom}
@keyframes hammer{0%,100%{transform:rotate(0)}50%{transform:rotate(-30deg)}}
.charge{animation:charge 1.6s ease-in-out infinite alternate}
@keyframes charge{from{transform:translateX(0)}to{transform:translateX(26px)}}
.jump{animation:jump 1s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center bottom}
.jump2{animation:jump 1s ease-in-out infinite alternate;animation-delay:-.5s;transform-box:fill-box;transform-origin:center bottom}
@keyframes jump{from{transform:translateY(0)}to{transform:translateY(-18px)}}
.heart{animation:heart 1.4s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
@keyframes heart{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.25);opacity:1}}
.notes{animation:steam 3s ease-in-out infinite}
.glow{animation:glow 2.6s ease-in-out infinite alternate}
@keyframes glow{from{filter:drop-shadow(0 0 0 rgba(255,210,94,0))}to{filter:drop-shadow(0 0 14px rgba(255,210,94,.9))}}
.swing{animation:swing 1.1s ease-in-out infinite;transform-box:fill-box;transform-origin:left bottom}
@keyframes swing{0%,100%{transform:rotate(0)}40%{transform:rotate(-28deg)}}
.fall{animation:fall 3s ease-in-out infinite alternate}
@keyframes fall{from{transform:translateY(-40px)}to{transform:translateY(20px)}}
.fall2{animation:fall2 2.6s ease-in infinite}
@keyframes fall2{0%{transform:translateY(-30px);opacity:0}20%{opacity:1}100%{transform:translateY(150px)}}
.fly{animation:fly 4s ease-in-out infinite alternate}
@keyframes fly{from{transform:translate(-30px,20px)}to{transform:translate(40px,-20px)}}
.flow{animation:flow 1.2s linear infinite}
@keyframes flow{to{stroke-dashoffset:-34}}
